package org.apache.commons.cli.help;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Queue;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for TextHelpAppendable.appendParagraph(CharSequence)
 */
public class TextHelpAppendableTest {

    // A subclass that captures the queue passed to printQueue so tests can inspect it
    static class CapturingTextHelpAppendable extends TextHelpAppendable {
        Queue<String> capturedQueue;

        public CapturingTextHelpAppendable(final Appendable output) {
            super(output);
        }

        // Override printQueue to capture the queue instead of printing to the Appendable
        @SuppressWarnings("unused")
        protected void printQueue(final Queue<String> queue) throws IOException {
            this.capturedQueue = queue;
        }
    }

    // A subclass that throws IOException from printQueue to test exception propagation
    static class ThrowingTextHelpAppendable extends TextHelpAppendable {
        public ThrowingTextHelpAppendable(final Appendable output) {
            super(output);
        }

        @SuppressWarnings("unused")
        protected void printQueue(final Queue<String> queue) throws IOException {
            throw new IOException("simulated print failure");
        }
    }

    private CapturingTextHelpAppendable capturing;
    private StringBuilder out;

    @BeforeEach
    public void setUp() {
        out = new StringBuilder();
        capturing = new CapturingTextHelpAppendable(out);
    }

    @Test
    public void testAppendParagraph_nullOrEmpty_doesNotInvokePrintQueue() throws Exception {
        // Access BLANK_LINE via reflection to ensure we compare against real sentinel if needed
        Field blankField = TextHelpAppendable.class.getDeclaredField("BLANK_LINE");
        blankField.setAccessible(true);
        String blankLine = (String) blankField.get(null);
        assertEquals("", blankLine);

        // null paragraph -> should not call printQueue
        capturing.appendParagraph(null);
        assertNull(capturing.capturedQueue, "printQueue should not have been called for null paragraph");

        // empty paragraph -> should not call printQueue
        capturing.appendParagraph("");
        assertNull(capturing.capturedQueue, "printQueue should not have been called for empty paragraph");
    }

    @Test
    public void testAppendParagraph_nonEmpty_invokesPrintQueueAndAddsBlankLine() throws Exception {
        // ensure capturedQueue is null initially
        assertNull(capturing.capturedQueue);

        // call with non-empty paragraph
        final String paragraph = "A simple paragraph";
        capturing.appendParagraph(paragraph);

        // printQueue should have been called and capturedQueue populated
        assertNotNull(capturing.capturedQueue, "printQueue should have been called for non-empty paragraph");
        assertFalse(capturing.capturedQueue.isEmpty(), "captured queue must not be empty");

        // last element should be the BLANK_LINE sentinel (reflectively obtained)
        final Field blankField = TextHelpAppendable.class.getDeclaredField("BLANK_LINE");
        blankField.setAccessible(true);
        final String blankLine = (String) blankField.get(null);

        // iterate to get last element
        String last = null;
        for (String s : capturing.capturedQueue) {
            last = s;
        }
        assertEquals(blankLine, last, "The last element of the queue must be the blank line sentinel");
    }

    @Test
    public void testAppendParagraph_printQueueThrows_propagatesIOException() {
        ThrowingTextHelpAppendable throwing = new ThrowingTextHelpAppendable(out);
        final String paragraph = "some content";
        IOException thrown = assertThrows(IOException.class, () -> throwing.appendParagraph(paragraph));
        assertEquals("simulated print failure", thrown.getMessage());
    }

    @Test
    public void testMakeColumnQueue_viaReflection_containsLeftPadAndProducesAtLeastOneLine() throws Exception {
        // Use reflection to invoke protected makeColumnQueue(CharSequence, TextStyle)
        Method makeColumnQueue = TextHelpAppendable.class.getDeclaredMethod("makeColumnQueue", CharSequence.class, TextStyle.class);
        makeColumnQueue.setAccessible(true);

        // Use the internal builder that the instance holds (getTextStyleBuilder is public as provided)
        TextStyle.Builder builder = capturing.getTextStyleBuilder();
        // set some predictable configuration: ensure left pad is non-negative and indent not huge
        builder.setLeftPad(1);
        builder.setIndent(0);
        builder.setMaxWidth(80);

        TextStyle style = builder.get();

        // invoke makeColumnQueue reflectively
        @SuppressWarnings("unchecked")
        Queue<String> queue = (Queue<String>) makeColumnQueue.invoke(capturing, "short", style);

        assertNotNull(queue, "makeColumnQueue must return a non-null queue");
        assertFalse(queue.isEmpty(), "queue must contain at least one line for non-empty input");

        // Ensure the produced line starts with a left pad (one space) as configured
        String first = queue.peek();
        assertNotNull(first);
        assertTrue(first.length() >= 1, "line should be at least as long as left pad");
        assertEquals(' ', first.charAt(0), "first character should be a single left pad space");
    }
}

